        int areaB = (bx2 - bx1) * (by2 - by1);
        int overlapW = Math.max(0, Math.min(ax2, bx2) - Math.max(ax1, bx1));
        int overlapH = Math.max(0, Math.min(ay2, by2) - Math.max(ay1, by1));
        return areaA + areaB - (overlapW * overlapH);
    }
}

